1 | #!/usr/bin/env node
2 | /**
3 |  * Inbin Gate as an MCP server for IBM Bob.
4 |  *
5 |  * Bob, in the "Gated Agent" mode, can change the world only through these
6 |  * tools. Each one asks the gate before acting. When the gate refuses, the tool
7 |  * returns the refusal as its result so Bob can read the reason, stop, and ask
8 |  * the developer, instead of retrying with a rephrasing.
9 |  */
10 | import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
11 | import { StdioServerTransport } from "@modelcontextprotocol/sdk/server/stdio.js";
12 | import { z } from "zod";
13 | import { execSync } from "node:child_process";
14 | import { writeFileSync, mkdirSync } from "node:fs";
15 | import { join, dirname, resolve } from "node:path";
16 | import { gate, readLog, sources, REPO } from "./core.mjs";
17 | 
18 | const server = new McpServer({ name: "inbin-gate", version: "0.1.0" });
19 | const text = (s) => ({ content: [{ type: "text", text: s }] });
20 | const sh = (cmd, cwd = REPO) => {
21 |   try { return execSync(cmd, { cwd, encoding: "utf8", stdio: ["ignore", "pipe", "pipe"], timeout: 120_000 }); }
22 |   catch (e) { return `exit ${e.status}\n${e.stdout || ""}${e.stderr || ""}`; }
23 | };
24 | 
25 | server.tool("run_command",
26 |   "Run a shell command in the repository. Executes only if the command is established by the developer's stated intent or by repository policy (package.json scripts, .gate/policy.json). Otherwise returns a refusal with the reason; do not retry with a rephrasing, ask the developer.",
27 |   { cmd: z.string() },
28 |   async ({ cmd }) => {
29 |     const d = gate("run_command", { cmd });
30 |     if (!d.allowed) return text(d.reason);
31 |     return text(`ALLOWED (${d.reason})\n$ ${cmd}\n${sh(cmd)}`);
32 |   });
33 | 
34 | server.tool("add_dependency",
35 |   "Add an npm dependency. Executes only if the package name is established by the developer's intent or already present in the repository. Otherwise returns a refusal; ask the developer.",
36 |   { name: z.string(), version: z.string().optional(), dev: z.boolean().optional() },
37 |   async ({ name, version, dev }) => {
38 |     const d = gate("add_dependency", { name });
39 |     if (!d.allowed) return text(d.reason);
40 |     const spec = version ? `${name}@${version}` : name;
41 |     return text(`ALLOWED (${d.reason})\n${sh(`npm install ${dev ? "-D " : ""}${spec} --no-audit --no-fund`)}`);
42 |   });
43 | 
44 | server.tool("edit_protected_file",
45 |   "Write a protected file (CI, deploy, package.json, .env, .gate). Executes only if the developer's intent names the path or policy lists it as editable. Ordinary source files do not need this tool.",
46 |   { path: z.string(), content: z.string() },
47 |   async ({ path, content }) => {
48 |     const d = gate("edit_protected_file", { path });
49 |     if (!d.allowed) return text(d.reason);
50 |     const p = resolve(REPO, path);
51 |     if (!p.startsWith(REPO)) return text("REFUSED by Inbin Gate: path escapes the repository");
52 |     mkdirSync(dirname(p), { recursive: true }); writeFileSync(p, content);
53 |     return text(`ALLOWED (${d.reason})\nwrote ${path} (${content.length} bytes)`);
54 |   });
55 | 
56 | server.tool("git_commit_push",
57 |   "Commit all changes and push to a branch. The branch must be established by the developer's intent or repository policy. Commit message is free text. Set INBIN_GATE_PUSH=0 to commit without pushing.",
58 |   { branch: z.string(), message: z.string() },
59 |   async ({ branch, message }) => {
60 |     const d = gate("git_commit_push", { branch, message });
61 |     if (!d.allowed) return text(d.reason);
62 |     const out = [sh(`git checkout -B ${JSON.stringify(branch)}`), sh("git add -A"), sh(`git commit -m ${JSON.stringify(message)} --allow-empty`)];
63 |     if (process.env.INBIN_GATE_PUSH !== "0") out.push(sh(`git push -u origin ${JSON.stringify(branch)}`));
64 |     return text(`ALLOWED (${d.reason})\n${out.join("\n")}`);
65 |   });
66 | 
67 | server.tool("gate_status",
68 |   "Show what the gate currently treats as established: the developer's stated intent and the repository policy. Read this before proposing an action you are unsure about.",
69 |   {},
70 |   async () => {
71 |     const s = sources();
72 |     return text(JSON.stringify({ repo: REPO, developerIntent: s.intent, repositoryPolicy: { commands: s.policy.commands, dependencies: s.policy.dependencies, branches: s.policy.branches } }, null, 2));
73 |   });
74 | 
75 | server.tool("gate_explain",
76 |   "Show the last decisions the gate made, with the derivation trace for each operand. Use it to explain a refusal to the developer.",
77 |   { last: z.number().int().min(1).max(50).optional() },
78 |   async ({ last }) => text(JSON.stringify(readLog(last ?? 5).map((e) => ({ at: e.at, action: e.action, args: e.args, allowed: e.allowed, reason: e.reason, operands: e.operands })), null, 2)));
79 | 
80 | const transport = new StdioServerTransport();
81 | await server.connect(transport);
