1 | /** Inbin Gate: load the channels from disk, decide, log. */
2 | import { readFileSync, existsSync, mkdirSync, appendFileSync, readdirSync, statSync } from "node:fs";
3 | import { join, resolve } from "node:path";
4 | import { homedir } from "node:os";
5 | import { decide } from "./decide.mjs";
6 | 
7 | export const HOME = process.env.INBIN_GATE_HOME || join(homedir(), ".inbin-gate");
8 | export const REPO = resolve(process.env.INBIN_GATE_REPO || process.cwd());
9 | 
10 | const readJSON = (p, d) => { try { return JSON.parse(readFileSync(p, "utf8")); } catch { return d; } };
11 | 
12 | /** The developer's channel: typed out of band with `gate intent "..."`, stored OUTSIDE the repository. */
13 | export function readIntent() {
14 |   const p = join(HOME, "intent.json");
15 |   return existsSync(p) ? readJSON(p, null) : null;
16 | }
17 | 
18 | /** The maintainers' channel: what the repository itself establishes. */
19 | export function readPolicy(repo = REPO) {
20 |   const pkg = readJSON(join(repo, "package.json"), {});
21 |   const policy = readJSON(join(repo, ".gate", "policy.json"), {});
22 |   const scripts = Object.keys(pkg.scripts || {}).flatMap((k) => [`npm run ${k}`, `npm ${k}`, pkg.scripts[k]]);
23 |   const deps = Object.keys({ ...(pkg.dependencies || {}), ...(pkg.devDependencies || {}) });
24 |   return {
25 |     commands: [...new Set([...(policy.commands || []), ...scripts, "npm install", "npm test", "npm ci"])],
26 |     dependencies: [...new Set([...(policy.dependencies || []), ...deps])],
27 |     branches: policy.branches || [],
28 |     editableProtectedFiles: policy.editableProtectedFiles || [],
29 |     protectedFiles: policy.protectedFiles || ["package.json", ".github/**", "ci/**", "deploy/**", ".env*", ".gate/**"],
30 |   };
31 | }
32 | 
33 | /** Not a channel. Collected only so a refusal can tell the human where a value came from. */
34 | export function readUntrusted(repo = REPO) {
35 |   const out = [];
36 |   const walk = (dir, depth) => {
37 |     if (depth > 4) return;
38 |     for (const name of readdirSync(dir)) {
39 |       if (name === "node_modules" || name.startsWith(".git")) continue;
40 |       const p = join(dir, name);
41 |       const st = statSync(p);
42 |       if (st.isDirectory()) walk(p, depth + 1);
43 |       else if (/\.(md|log|txt)$/i.test(name) && name !== "TASKS.md" && st.size < 512 * 1024) out.push({ file: p.slice(repo.length + 1), text: readFileSync(p, "utf8") });
44 |     }
45 |   };
46 |   try { walk(repo, 0); } catch {}
47 |   return out;
48 | }
49 | 
50 | export function sources(repo = REPO) {
51 |   return { intent: readIntent(), policy: readPolicy(repo), untrusted: readUntrusted(repo) };
52 | }
53 | 
54 | export function gate(action, args, repo = REPO) {
55 |   const d = decide(action, args, sources(repo));
56 |   log({ at: new Date().toISOString(), repo, action, args, ...d });
57 |   return d;
58 | }
59 | 
60 | export function log(entry) {
61 |   mkdirSync(HOME, { recursive: true });
62 |   appendFileSync(join(HOME, "decisions.jsonl"), JSON.stringify(entry) + "\n");
63 |   try { mkdirSync(join(REPO, ".gate"), { recursive: true }); appendFileSync(join(REPO, ".gate", "decisions.jsonl"), JSON.stringify(entry) + "\n"); } catch {}
64 | }
65 | 
66 | export function readLog(n = 20) {
67 |   const p = join(HOME, "decisions.jsonl");
68 |   if (!existsSync(p)) return [];
69 |   return readFileSync(p, "utf8").trim().split("\n").filter(Boolean).slice(-n).map((l) => JSON.parse(l));
70 | }
