1 | /**
2 |  * Predicate-scoped authority: the pure core.
3 |  *
4 |  * Minting boundary (spec 5.4) and operative view (spec 5.5) as pure
5 |  * functions over an in-memory store value. No schema, no HTTP, no
6 |  * I/O; the substrate (Stage 1+) is built under this interface after
7 |  * the semantics are proven by lib/authority/acceptance.test.ts.
8 |  *
9 |  * Two invariants the whole design hangs on:
10 |  *   - The submission's `object` is OPAQUE during class derivation
11 |  *     (spec 5.9.2). It is stored by reference, verbatim, and no code
12 |  *     in mint()'s derivation reads any part of it. The acceptance
13 |  *     suite proves this with a Proxy tripwire (T6). The one place
14 |  *     values are legitimately compared is contradicts() at conflict-
15 |  *     indexing time, which by definition runs only against ALREADY
16 |  *     STORED assertions over the same subject and predicate, never
17 |  *     to derive class.
18 |  *   - Recency NEVER crosses a class boundary: partition by class
19 |  *     first, select the highest occupied class, order by time only
20 |  *     within it (spec 5.5).
21 |  */
22 | export const AUTHORITY_CLASSES = [
23 |     "ESTABLISHING",
24 |     "CORROBORATING",
25 |     "PROPOSING",
26 | ];
27 | /** Higher = more authoritative. */
28 | export function classRank(c) {
29 |     return AUTHORITY_CLASSES.length - AUTHORITY_CLASSES.indexOf(c);
30 | }
31 | export function emptyStore(capabilities = [], recognitions = []) {
32 |     return { capabilities, recognitions, assertions: [], conflicts: [] };
33 | }
34 | /**
35 |  * Evidence-output bound. `defeated` carries at most this many ids
36 |  * (most recent first); `defeatedCount` is always the true total. The
37 |  * cap keeps the operative response bounded under high-volume
38 |  * predicates; a full-conflict-set read variant (spec 5.9.7's third
39 |  * operation) can return everything unbounded when built.
40 |  */
41 | export const DEFEATED_LIST_CAP = 20;
42 | /**
43 |  * Conflict-set bound (spec 5.9.6). Comparisons at mint run against
44 |  * at most this many prior assertions PER CLASS (the most recent by
45 |  * valid_from, among those valid at mint time). Bounds the worst case
46 |  * where a flood of PROPOSING writes (which any authenticated sender
47 |  * can produce, per T6) would otherwise cost O(N) comparisons per
48 |  * mint and O(N^2) edges in storage. Authority is unaffected: the
49 |  * operative view derives `defeated` from the candidate set, never
50 |  * from the conflict index.
51 |  */
52 | export const CONFLICT_CANDIDATE_BOUND = 25;
53 | // ------------------------------------------------------------- matching
54 | /** "a.b" matches exact "a.b"; "a.*" matches "a.b" and "a.b.c". */
55 | function predicateInScope(predicate, scope) {
56 |     for (const s of scope) {
57 |         if (s.endsWith(".*")) {
58 |             if (predicate.startsWith(s.slice(0, -1)))
59 |                 return true; // keeps the dot
60 |         }
61 |         else if (predicate === s) {
62 |             return true;
63 |         }
64 |     }
65 |     return false;
66 | }
67 | function subjectInScope(subject, scope) {
68 |     return scope.match === "prefix"
69 |         ? subject.startsWith(scope.value)
70 |         : subject === scope.value;
71 | }
72 | /** Exact match, or a single-"*" glob within one binding entry. */
73 | function channelMatches(channelId, binding) {
74 |     for (const b of binding) {
75 |         if (!b.includes("*")) {
76 |             if (channelId === b)
77 |                 return true;
78 |             continue;
79 |         }
80 |         const [head, tail] = b.split("*", 2);
81 |         if (channelId.length >= head.length + tail.length &&
82 |             channelId.startsWith(head) &&
83 |             channelId.endsWith(tail)) {
84 |             return true;
85 |         }
86 |     }
87 |     return false;
88 | }
89 | function windowValid(cap, now) {
90 |     if (cap.notBefore > now || cap.notAfter < now)
91 |         return false;
92 |     if (cap.revokedAt != null && cap.revokedAt <= now)
93 |         return false;
94 |     return true;
95 | }
96 | /** Structural equality over JSON-ish values. Used ONLY by
97 |  * contradicts(), against stored assertions, never for derivation. */
98 | function deepEqual(x, y) {
99 |     if (Object.is(x, y))
100 |         return true;
101 |     if (typeof x !== "object" || typeof y !== "object" || x === null || y === null)
102 |         return false;
103 |     const ax = Array.isArray(x);
104 |     if (ax !== Array.isArray(y))
105 |         return false;
106 |     if (ax) {
107 |         const xa = x;
108 |         const ya = y;
109 |         return xa.length === ya.length && xa.every((v, i) => deepEqual(v, ya[i]));
110 |     }
111 |     const xk = Object.keys(x);
112 |     const yk = Object.keys(y);
113 |     if (xk.length !== yk.length)
114 |         return false;
115 |     return xk.every((k) => deepEqual(x[k], y[k]));
116 | }
117 | /** Default contradiction predicate (spec 5.9.5): same subject and
118 |  * predicate, unequal object. Callers guarantee same subject+predicate.
119 |  *
120 |  * Hardened: the objects are attacker-controlled, so the comparison
121 |  * itself is an attack surface (throwing getters, reference cycles
122 |  * overflowing the recursion). A comparison that fails is treated as
123 |  * a CONTRADICTION, not swallowed: we cannot prove the values equal,
124 |  * so the edge is written and the evidence output stays complete. A
125 |  * hostile object can therefore force a conflict edge onto its own
126 |  * assertion, never suppress one, and never abort the mint. */
127 | function contradicts(a, b) {
128 |     try {
129 |         return !deepEqual(a.object, b.object);
130 |     }
131 |     catch {
132 |         return true;
133 |     }
134 | }
135 | // ----------------------------------------------------------------- mint
136 | /**
137 |  * Spec 5.4. Steps map 1:1 to the pseudocode there. The strip of step
138 |  * 2 is realized as the preferred opacity embodiment: the object is
139 |  * carried by reference and never read.
140 |  */
141 | export function mint(store, submission, ctx, now, opts = {}) {
142 |     // 1. Authenticate. No authentication, no write.
143 |     if (ctx.principalId === null)
144 |         return { rejected: "unauthenticated" };
145 |     const principal = ctx.principalId;
146 |     // 2. Opacity in lieu of strip (spec 5.4 step 2, preferred form):
147 |     //    submission.object is not read anywhere below; it is attached
148 |     //    to the record by reference at step 5.
149 |     // 3. Match capabilities on ALL of principal, subject, predicate,
150 |     //    channel, time.
151 |     const trace = ["principal:authenticated"];
152 |     // Local = capabilities of the minting context's own trust domain.
153 |     // Foreign-domain capabilities are reachable ONLY through the
154 |     // recognition hook below; without this filter a foreign grant
155 |     // would match as if it were local and bypass the 5.9.4 gate.
156 |     let candidates = store.capabilities.filter((cap) => cap.trustDomain === ctx.trustDomain &&
157 |         cap.principalId === principal &&
158 |         predicateInScope(submission.predicate, cap.predicateScope) &&
159 |         subjectInScope(submission.subject, cap.subjectScope) &&
160 |         channelMatches(ctx.channelId, cap.channelBinding) &&
161 |         windowValid(cap, now));
162 |     // 3a. Recognition hook (spec 5.9.4): only after local matching
163 |     //     yields no candidate, and before defaulting to PROPOSING.
164 |     //     Foreign capabilities are admitted only for predicates a live
165 |     //     recognition enumerates, capped at max_class.
166 |     let capFor = (cap) => cap.authorityClass;
167 |     if (candidates.length === 0) {
168 |         const recognized = store.recognitions.filter((r) => r.recognizingDomain === ctx.trustDomain &&
169 |             r.notAfter >= now &&
170 |             predicateInScope(submission.predicate, r.recognizedPredicates));
171 |         if (recognized.length > 0) {
172 |             const caps = new Map();
173 |             for (const r of recognized) {
174 |                 const foreign = store.capabilities.filter((cap) => cap.trustDomain === r.recognizedDomain &&
175 |                     cap.trustDomain !== ctx.trustDomain &&
176 |                     cap.principalId === principal &&
177 |                     predicateInScope(submission.predicate, cap.predicateScope) &&
178 |                     subjectInScope(submission.subject, cap.subjectScope) &&
179 |                     channelMatches(ctx.channelId, cap.channelBinding) &&
180 |                     windowValid(cap, now));
181 |                 for (const cap of foreign) {
182 |                     const capped = classRank(cap.authorityClass) > classRank(r.maxClass)
183 |                         ? r.maxClass
184 |                         : cap.authorityClass;
185 |                     const prev = caps.get(cap.capabilityId);
186 |                     if (!prev || classRank(capped) > classRank(prev)) {
187 |                         caps.set(cap.capabilityId, capped);
188 |                     }
189 |                 }
190 |             }
191 |             if (caps.size > 0) {
