278 |  * capability demotes to PROPOSING. Never promotes past the stored
279 |  * class.
280 |  */
281 | function classAtRead(a, store, at, mode) {
282 |     if (mode === "frozen")
283 |         return a.authority.class;
284 |     const stored = a.authority.class;
285 |     if (a.authority.capabilityId === null)
286 |         return stored; // PROPOSING stays
287 |     const cap = store.capabilities.find((c) => c.capabilityId === a.authority.capabilityId);
