289 |         windowValid(cap, at) &&
290 |         predicateInScope(a.predicate, cap.predicateScope) &&
291 |         subjectInScope(a.subject, cap.subjectScope) &&
292 |         channelMatches(a.ingestedVia, cap.channelBinding);
293 |     if (!stillGrants)
294 |         return "PROPOSING";
295 |     return classRank(cap.authorityClass) < classRank(stored)
296 |         ? cap.authorityClass
