299 | export function conflictSet(store, subject, predicate, at, opts = {}) {
300 |     // Spec 5.9.7, third operation: the full conflict set grouped by
301 |     // class rather than a single value. Same candidate rule and same
302 |     // evaluation modes as operative(); no cap.
303 |     const mode = opts.mode ?? "frozen";
304 |     const candidates = store.assertions.filter((a) => a.subject === subject && a.predicate === predicate && a.validFrom <= at);
305 |     const classes = AUTHORITY_CLASSES.map((cls) => ({
306 |         class: cls,
307 |         assertions: candidates
308 |             .filter((a) => classAtRead(a, store, at, mode) === cls)
309 |             // Server ingestion order, matching operative() (review Q2).
310 |             .sort((x, y) => y.recordedAt.getTime() - x.recordedAt.getTime() ||
311 |             (y.assertionId > x.assertionId ? 1 : -1)),
312 |     })).filter((g) => g.assertions.length > 0);
313 |     return { classes, total: candidates.length };
314 | }
315 | /**
316 |  * Spec 5.5. Partition strictly by derived class; recency applies only
317 |  * inside the selected class. The partition input is the evaluation
