319 |  * re-derived against the capability store as of `at` (reevaluated).
320 |  */
321 | export function operative(store, subject, predicate, at, opts = {}) {
322 |     const mode = opts.mode ?? "frozen";
323 |     const candidates = store.assertions.filter((a) => a.subject === subject && a.predicate === predicate && a.validFrom <= at);
