330 |         // Recency is SERVER ingestion time (recordedAt), never the
331 |         // client-supplied validFrom. validFrom is honored only for
332 |         // visibility (the `validFrom <= at` candidate filter above); if it
333 |         // also drove ordering, a caller could future-date or bump an
334 |         // assertion to jump the recency tie-break (review 2026-08-25, Q2).
335 |         // Tie-break within identical recordedAt: assertionId (server id).
336 |         const winner = partition.reduce((w, a) => {
337 |             if (a.recordedAt > w.recordedAt)
338 |                 return a;
339 |             if (a.recordedAt < w.recordedAt)
340 |                 return w;
341 |             return a.assertionId > w.assertionId ? a : w;
342 |         });
