348 |             value: winner.object,
349 |             assertionId: winner.assertionId,
350 |             capabilityId: winner.authority.capabilityId,
351 |             derivation: winner.authority.derivation,
352 |             class: cls,
353 |             defeated: losers.slice(0, DEFEATED_LIST_CAP).map((a) => a.assertionId),
